"""UnifiedToolHub: one internal schema for every benchmark, one outbound format for magpie.

Every dataset (BFCL V1/V3, ToolCallBench-CN) is normalized into `ToolCase`: a list of
turns, a flat tool registry (OpenAI function schema), and gold tool-calls. The hub then
renders OpenAI-compatible `messages` + `tools` for the magpie gateway and parses the
model's `tool_calls` back into a canonical `Call` list for scoring.
"""
from __future__ import annotations
import json, re
from dataclasses import dataclass, field
from typing import Any, Optional

# ---------- canonical internal schema ----------
@dataclass
class Call:
    name: str
    arguments: dict

    def key(self) -> str:
        return f"{self.name}::{json.dumps(self.arguments, sort_keys=True, ensure_ascii=False)}"


@dataclass
class ToolCase:
    cid: str
    source: str            # 'bfcl_v1' | 'toolcallbench_cn' | 'bfcl_v3'
    category: str          # simple/multiple/parallel/irrelevance/arg_hard/multi_turn/...
    tools: list[dict]      # OpenAI function schemas: {type:function, function:{name,description,parameters}}
    turns: list[dict]      # list of {"role","content"} user/assistant/tool messages (without system)
    gold: list[Call]       # expected tool calls (empty = should not call any tool)
    meta: dict = field(default_factory=dict)

    def messages(self, system: Optional[str] = None) -> list[dict]:
        msgs = []
        if system:
            msgs.append({"role": "system", "content": system})
        msgs.extend(self.turns)
        return msgs

    def opens(self) -> bool:
        """True if this case expects at least one tool call."""
        return len(self.gold) > 0


# ---------- normalize helpers ----------
def _truncate_schema(fn: dict) -> dict:
    """BFCL uses python type names ('dict','integer','string'...); normalize to json-schema."""
    ty_map = {"dict": "object", "integer": "integer", "string": "string", "number": "number",
              "boolean": "boolean", "list": "array", "float": "number", "any": "string"}
    params = fn.get("parameters") or {"type": "object", "properties": {}}
    def fix(schema):
        if not isinstance(schema, dict):
            return schema
        out = dict(schema)
        t = out.get("type")
        if isinstance(t, str) and t in ty_map:
            out["type"] = ty_map[t]
        if "properties" in out and isinstance(out["properties"], dict):
            out["properties"] = {k: fix(v) for k, v in out["properties"].items()}
        if "items" in out:
            out["items"] = fix(out["items"])
        return out
    return {"type": "function",
            "function": {"name": fn["name"],
                         "description": fn.get("description", ""),
                         "parameters": fix(params)}}


# ---------- BFCL adapters ----------
def load_bfcl_single(path: str, source="bfcl_v1") -> list[ToolCase]:
    """BFCL simple/multiple/parallel/irrelevance: one-turn, gold in 'possible_answer' sibling file."""
    raise NotImplementedError  # gold lives in a separate possible_answer file; see bfcl_loader


def parse_model_calls(choice_message: dict) -> list[Call]:
    """Parse an assistant message's tool_calls (OpenAI shape) into Call list."""
    out = []
    for tc in (choice_message.get("tool_calls") or []):
        fn = tc.get("function", {})
        name = fn.get("name", "")
        raw = fn.get("arguments", "")
        args = parse_args(raw)
        out.append(Call(name, args))
    return out


def parse_args(raw: Any) -> dict:
    if isinstance(raw, dict):
        return raw
    if not isinstance(raw, str) or not raw.strip():
        return {}
    s = raw.strip()
    # strip markdown fences
    s = re.sub(r"^```(json)?", "", s).strip()
    s = re.sub(r"```$", "", s).strip()
    try:
        v = json.loads(s)
        return v if isinstance(v, dict) else {"__raw__": v}
    except Exception:
        # try to extract first {...} block
        m = re.search(r"\{.*\}", s, re.S)
        if m:
            try:
                v = json.loads(m.group(0))
                return v if isinstance(v, dict) else {"__raw__": v}
            except Exception:
                pass
        return {"__unparsable__": s}

