"""BFCL loaders (V1 single-turn + V3 multi-turn) into the unified ToolCase schema."""
from __future__ import annotations
import json, os, re
from hub import ToolCase, Call, _truncate_schema

BFCL_DIR = os.path.join(os.path.dirname(__file__), "..", "data", "bfcl")
PA_DIR = os.path.join(BFCL_DIR, "possible_answer")


def _ld(path):
    with open(path, encoding="utf-8") as f:
        return [json.loads(l) for l in f if l.strip()]


def _tool_name(fn):
    return fn["name"]


def _gold_truth_to_calls(ground_truth: list[dict]) -> list[Call]:
    """ground_truth: [ { 'func' or 'cls.method': {param: [acceptable...] } } ].
    Take the first acceptable value for each param for the canonical gold."""
    calls = []
    for item in ground_truth:
        for fname, params in item.items():
            args = {}
            for p, vals in (params or {}).items():
                if isinstance(vals, list) and vals:
                    args[p] = vals[0]
                else:
                    args[p] = vals
            calls.append(Call(fname, args))
    return calls


def _norm_multi_turn_gold(fname, args):
    """Multi-turn gold comes flat: {'func': {...}} similar shape."""
    return Call(fname, args)


def load_single(category: str) -> list[ToolCase]:
    """category in: simple, multiple, parallel, irrelevance."""
    qfile = os.path.join(BFCL_DIR, f"BFCL_v3_{category}.json")
    qs = _ld(qfile)
    gold = {}
    if category != "irrelevance":
        gold = {g["id"]: g["ground_truth"] for g in _ld(os.path.join(PA_DIR, f"BFCL_v3_{category}.json"))}
    cases = []
    for q in qs:
        tools = [_truncate_schema(fn) for fn in q.get("function", [])]
        turns = q["question"][0]  # single-turn: [[{role,content}]]
        if category == "irrelevance":
            g = []
        else:
            g = _gold_truth_to_calls(gold.get(q["id"], []))
        cases.append(ToolCase(cid=q["id"], source="bfcl_v1", category=category,
                              tools=tools, turns=turns, gold=g,
                              meta={"possible_answer": gold.get(q["id"]) if category != "irrelevance" else []}))
    return cases


# ---- multi-turn ----
def _exec_category(cat):
    """multi-turn categories have per-turn possible_answer nested by turn index."""
    return cat


def load_multi_turn(category: str = "multi_turn_base", limit=None) -> list[ToolCase]:
    qfile = os.path.join(BFCL_DIR, f"BFCL_v3_{category}.json")
    qs = _ld(qfile)
    pa = _ld(os.path.join(PA_DIR, f"BFCL_v3_{category}.json"))
    pa_by_id = {p["id"]: p["ground_truth"] for p in pa}
    cases = []
    for q in qs:
        if limit and len(cases) >= limit:
            break
        tools = [_truncate_schema(fn) for fn in q.get("function", [])]
        # question is a list of turns; each turn is a list of messages
        turns = []
        for turn in q["question"]:
            turns.extend(turn)
        gt = pa_by_id.get(q["id"], [])  # list per turn of list of {func:{args}}
        # flatten all turns' expected calls for a coarse gold (multi-turn scored separately)
        gold = []
        for turn_gt in gt:
            gold.extend(_gold_truth_to_calls(turn_gt))
        cases.append(ToolCase(cid=q["id"], source="bfcl_v3", category=category,
                              tools=tools, turns=turns, gold=gold,
                              meta={"multi_turn_truth": gt, "involved_classes": q.get("involved_classes")}))
    return cases

"""Scoring for tool calls: name match + tolerant argument match against acceptable-value gold.

Score modes:
  - exact_set: set of calls must equal gold set (parallel / multiple)
  - each: every gold call must be satisfied (partial ok if single)
  - irrelevance: model must emit NO tool call
Argument matching: a gold param with a list of acceptable values passes if the model's
value matches ANY acceptable value (string-ish comparison, numeric tolerance, bool, nested).
"""
from __future__ import annotations
import json
from hub import Call


def _canon(v):
    if isinstance(v, bool):
        return v
    if isinstance(v, (int, float)):
        return float(v)
    if isinstance(v, str):
        s = v.strip()
        # numeric strings
        try:
            return float(s)
        except Exception:
            return s
    return v


def _eq(a, b) -> bool:
    """Loose equality between a model value and one acceptable value."""
    a, b = _canon(a), _canon(b)
    if a == b:
        return True
    if isinstance(a, float) and isinstance(b, float):
        return abs(a - b) < 1e-6
    # string compare normalized
    sa = str(a).strip().lower()
    sb = str(b).strip().lower()
    if sa == sb:
        return True
    # bool-ish
    if sa in ("true", "yes") and sb in ("true", "yes"):
        return True
    if sa in ("false", "no") and sb in ("false", "no"):
        return True
    if sa in ("", "none", "null") and sb in ("", "none", "null"):
        return True
    return False


def args_match(model_args: dict, acceptable: dict) -> tuple[bool, list]:
    """acceptable: {param: [acceptable values]} or {param: list}. Returns (ok, missing)."""
    if not isinstance(acceptable, dict):
        return True, []
    missing = []
    for p, vals in acceptable.items():
        ok_vals = vals if isinstance(vals, list) else [vals]
        if p not in model_args:
            # allow optional param with empty acceptable set? treat as missing
            missing.append(p)
            continue
        mv = model_args[p]
        if not any(_eq(mv, av) for av in ok_vals):
            missing.append(p)
    return (len(missing) == 0), missing


def _name_match(model_name: str, gold_name: str) -> bool:
    if model_name == gold_name:
        return True
    # gold may be Class.method while schema name is method (or vice versa)
    if "." in gold_name and model_name == gold_name.split(".")[-1]:
        return True
    if "." in model_name and gold_name == model_name.split(".")[-1]:
        return True
    return False


def score_case(pred_calls: list[Call], gold_calls: list[Call],
               meta: dict, category: str) -> dict:
    """Return {'pass':bool,'detail':...}. Handles irrelevance and multi-call."""
    # irrelevance / no-call expected
    if category == "irrelevance" or (len(gold_calls) == 0 and not meta.get("possible_answer")):
        passed = len(pred_calls) == 0
        return {"pass": passed, "kind": "irrelevance",
                "reason": "no call expected" if passed else f"emitted {len(pred_calls)} unexpected call(s)"}

    pa = meta.get("possible_answer") or []
    # Build acceptable per gold call. pa items are {fname: {param: [vals]}}
    leaves = []   # (name, acceptable_params)
    if pa:
        for item in pa:
            for fname, params in item.items():
                leaves.append((fname, params))
    else:
        for g in gold_calls:
            leaves.append((g.name, {k: [v] for k, v in g.arguments.items()}))

    if not leaves:
        return {"pass": len(pred_calls) == 0, "kind": category, "reason": "no gold"}

    # try to match each gold leaf to a distinct predicted call
    used = set()
    matched = 0
    detail = []
    for fname, params in leaves:
        hit = -1
        for i, pc in enumerate(pred_calls):
            if i in used:
                continue
            if _name_match(pc.name, fname):
                ok, missing = args_match(pc.arguments, params)
                if ok:
                    hit = i
                    break
        if hit >= 0:
            used.add(hit)
            matched += 1
            detail.append(f"OK {fname}")
        else:
            # diagnose: name present but args wrong?
            name_present = any(_name_match(pc.name, fname) for pc in pred_calls)
            detail.append(f"MISS {fname} ({'args' if name_present else 'name/absent'})")

    kind = "parallel" if len(leaves) > 1 else "single"
    strict = category in ("simple", "multiple", "parallel", "parallel_multiple")
    if strict:
        # must match all gold AND no extra calls
        passed = matched == len(leaves) and len(pred_calls) == len(leaves)
    else:
        passed = matched == len(leaves)
    return {"pass": passed, "kind": kind, "matched": matched,
            "n_gold": len(leaves), "n_pred": len(pred_calls), "detail": detail}

