"""Scoring for tool calls: name match + tolerant argument match against acceptable-value gold.

Argument matching rules (BFCL-aligned):
  * Only params listed as `required` in the tool schema must be present and match.
    Optional params present in gold are ignored if the model omits them; if the model
    DOES supply them they are not penalised for a different-but-valid choice either
    (BFCL default: ignore optional unless wrong presence breaks anything).
  * An acceptable list [v1, v2, ...] passes if the model value ~equals ANY element.
  * Nested dict/list values are deep-compared.
"""
from __future__ import annotations
import json


def _canon(v):
    if isinstance(v, bool):
        return v
    if isinstance(v, (int, float)):
        return float(v)
    if isinstance(v, str):
        s = v.strip()
        try:
            return float(s)
        except Exception:
            return s
    return v


def _eq(a, b) -> bool:
    # nested deep compare
    if isinstance(a, dict) and isinstance(b, dict):
        return all(k in a and _eq(a[k], b[k]) for k in b) and set(a.keys()) == set(b.keys())
    if isinstance(a, (list, tuple)) and isinstance(b, (list, tuple)):
        return len(a) == len(b) and all(_eq(x, y) for x, y in zip(a, b))
    a, b = _canon(a), _canon(b)
    if a == b:
        return True
    if isinstance(a, float) and isinstance(b, float):
        return abs(a - b) < 1e-6
    sa, sb = str(a).strip().lower(), str(b).strip().lower()
    if sa == sb:
        return True
    if sa in ("true", "yes") and sb in ("true", "yes"):
        return True
    if sa in ("false", "no") and sb in ("false", "no"):
        return True
    if sa in ("", "none", "null") and sb in ("", "none", "null"):
        return True
    return False


def args_match(model_args: dict, acceptable: dict, required: list[str] | None) -> tuple[bool, list]:
    """acceptable: {param: [acceptable values]}. required: schema required list.
    Only required params are enforced. Returns (ok, missing_required)."""
    if not isinstance(acceptable, dict):
        return True, []
    req = set(required) if required is not None else set(acceptable.keys())
    missing = []
    for p in req:
        if p not in acceptable:
            continue
        ok_vals = acceptable[p] if isinstance(acceptable[p], list) else [acceptable[p]]
        if p not in model_args:
            missing.append(p)
            continue
        if not any(_eq(model_args[p], av) for av in ok_vals):
            missing.append(p)
    return (len(missing) == 0), missing


def _name_match(model_name: str, gold_name: str) -> bool:
    if model_name == gold_name:
        return True
    if "." in gold_name and model_name == gold_name.split(".")[-1]:
        return True
    if "." in model_name and gold_name == model_name.split(".")[-1]:
        return True
    return False


def _schema_required(tools: list[dict]) -> dict:
    """name -> required list, from OpenAI function schemas."""
    out = {}
    for t in tools or []:
        fn = t.get("function", t)
        out[fn.get("name")] = (fn.get("parameters") or {}).get("required", [])
        # also map Class.method alias
        if "." in fn.get("name", ""):
            out[fn["name"].split(".")[-1]] = (fn.get("parameters") or {}).get("required", [])
    return out


def score_case(pred_calls, gold_calls, meta: dict, category: str, tools=None) -> dict:
    req_map = _schema_required(tools) if tools else {}
    if category == "irrelevance" or (len(gold_calls) == 0 and not meta.get("possible_answer")):
        passed = len(pred_calls) == 0
        return {"pass": passed, "kind": "irrelevance",
                "reason": "no call expected" if passed else f"emitted {len(pred_calls)} unexpected call(s)"}

    pa = meta.get("possible_answer") or []
    leaves = []
    if pa:
        for item in pa:
            for fname, params in item.items():
                leaves.append((fname, params))
    else:
        for g in gold_calls:
            leaves.append((g.name, {k: [v] for k, v in g.arguments.items()}))
    if not leaves:
        return {"pass": len(pred_calls) == 0, "kind": category, "reason": "no gold"}

    used, matched, detail = set(), 0, []
    for fname, params in leaves:
        req = req_map.get(fname)
        hit = -1
        for i, pc in enumerate(pred_calls):
            if i in used:
                continue
            if _name_match(pc.name, fname):
                ok, _m = args_match(pc.arguments, params, req)
                if ok:
                    hit = i
                    break
        if hit >= 0:
            used.add(hit); matched += 1; detail.append(f"OK {fname}")
        else:
            name_present = any(_name_match(pc.name, fname) for pc in pred_calls)
            detail.append(f"MISS {fname} ({'args' if name_present else 'name/absent'})")

    kind = "parallel" if len(leaves) > 1 else "single"
    strict = category in ("simple", "multiple", "parallel", "parallel_multiple")
    if strict:
        passed = matched == len(leaves) and len(pred_calls) == len(leaves)
    else:
        passed = matched == len(leaves)
    return {"pass": passed, "kind": kind, "matched": matched,
            "n_gold": len(leaves), "n_pred": len(pred_calls), "detail": detail}

