tool_input.content:
"""BFCL V3 multi-turn stateful runner.

For each case: iterate turns. At each turn append the user message, ask the model
(with the full tool set), parse its tool calls, score against that turn's expected
call list, then append a synthetic tool result per call and continue. This exercises
real state tracking (path/context carried across turns) like an agent loop.
"""
from __future__ import annotations
import argparse, ast, json, os, re, sys, time
from concurrent.futures import ThreadPoolExecutor, as_completed
sys.path.insert(0, os.path.dirname(__file__))
import magpie
from hub import _truncate_schema, parse_model_calls, Call
from scorer import args_match, _name_match, _schema_required

DATA = os.path.join(os.path.dirname(__file__), "..", "data", "bfcl")
PA = os.path.join(DATA, "possible_answer")
OUT = os.path.join(os.path.dirname(__file__), "..", "out")
MODELS = os.path.join(os.path.dirname(__file__), "..", "models.json")


def _ld(p):
    with open(p, encoding="utf-8") as f:
        return [json.loads(l) for l in f if l.strip()]


_CALL_RE = re.compile(r"^([A-Za-z_][\w.]*)\s*\((.*)\)$")


def parse_gold_call(s: str) -> Call:
    """'func(k=v)' -> Call(func, {k:v}) with python literal eval of values."""
    s = s.strip()
    m = _CALL_RE.match(s)
    if not m:
        return Call(s, {})
    name, argstr = m.group(1), m.group(2)
    args = {}
    if argstr.strip():
        # split top-level commas
        depth, cur, parts = 0, "", []
        for ch in argstr:
            if ch in "([{":
                depth += 1
            elif ch in ")]}":
                depth -= 1
            if ch == "," and depth == 0:
                parts.append(cur); cur = ""
            else:
                cur += ch
        if cur.strip():
            parts.append(cur)
        for p in parts:
            if "=" not in p:
                continue
            k, v = p.split("=", 1)
            k = k.strip()
            v = v.strip()
            try:
                val = ast.literal_eval(v)
            except Exception:
                val = v.strip("'\"")
            args[k] = val
    return Call(name, args)


def turn_score(preds: list[Call], gold_turn: list[str], req_map: dict) -> dict:
    """A turn requires emitting all gold calls (subset args). Extra benign calls ignored,
    but we require every gold call be present. Empty gold turn = should emit no call."""
    expected = [parse_gold_call(s) for s in gold_turn]
    if not expected:
        return {"pass": len(preds) == 0, "n_gold": 0, "n_pred": len(preds)}
    used, matched = set(), 0
    for g in expected:
        hit = -1
        for i, p in enumerate(preds):
            if i in used:
                continue
            if _name_match(p.name, g.name):
                req = req_map.get(g.name, list(g.arguments.keys()))
                ok, _ = args_match(p.arguments, {k: [v] for k, v in g.arguments.items()}, req)
                if ok:
                    hit = i
                    break
        if hit >= 0:
            used.add(hit); matched += 1
    return {"pass": matched == len(expected), "matched": matched,
            "n_gold": len(expected), "n_pred": len(preds)}


def run_case(model: str, q: dict, pa_turns: list[list[str]]) -> dict:
    tools = [_truncate_schema(fn) for fn in q.get("function", [])]
    req_map = _schema_required(tools)
    msgs = []
    turn_results = []
    t0 = time.time()
    for ti, turn in enumerate(q["question"]):
        # append user messages of this turn
        for m in turn:
            msgs.append({"role": m.get("role", "user"), "content": m.get("content", "")})
        try:
            resp = magpie.chat(model, msgs, tools or None, max_tokens=1024)
        except Exception as e:
            turn_results.append({"turn": ti, "error": repr(e), "pass": False})
            break
        preds = parse_model_calls(resp)
        gold = pa_turns[ti] if ti < len(pa_turns) else []
        sc = turn_score(preds, gold, req_map)
        turn_results.append({"turn": ti, "pass": sc["pass"], "pred": [p.name for p in preds],
                             "gold": gold, **sc})
        # append assistant tool_calls + synthetic tool outputs so state continues
        if preds:
            tool_calls = [{"id": f"call_{ti}_{i}", "type": "function",
                           "function": {"name": p.name, "arguments": json.dumps(p.arguments, ensure_ascii=False)}}
                          for i, p in enumerate(preds)]
            msgs.append({"role": "assistant", "content": resp.get("content") or "", "tool_calls": tool_calls})
            for tc in tool_calls:
                msgs.append({"role": "tool", "tool_call_id": tc["id"], "content": "OK (simulated result)"})
        else:
            msgs.append({"role": "assistant", "content": resp.get("content") or ""})
    n = len(turn_results)
    npass = sum(1 for r in turn_results if r.get("pass"))
    return {"cid": q["id"], "model": model, "turns": turn_results,
            "turn_acc": round(npass / n, 4) if n else 0, "n_turns": n,
            "all_pass": npass == n and n > 0, "latency": round(time.time() - t0, 2)}


def main():
    ap = argparse.ArgumentParser()
    ap.add_argument("--models", nargs="*", default=None)
    ap.add_argument("--limit", type=int, default=20)
    ap.add_argument("--category", default="multi_turn_base")
    ap.add_argument("--workers", type=int, default=3)
    ap.add_argument("--tag", default=None)
    args = ap.parse_args()
    os.makedirs(OUT, exist_ok=True)
    models = args.models or json.load(open(MODELS, encoding="utf-8"))
    qs = _ld(os.path.join(DATA, f"BFCL_v3_{args.category}.json"))[:args.limit]
    pa = {p["id"]: p["ground_truth"] for p in _ld(os.path.join(PA, f"BFCL_v3_{args.category}.json"))}

    print(f"[v3:{args.category}] {len(qs)} cases x {len(models)} models")
    all_res = {}
    t0 = time.time()
    for model in models:
        recs = []
        with ThreadPoolExecutor(max_workers=args.workers) as ex:
            futs = {ex.submit(run_case, model, q, pa.get(q["id"], [])): q for q in qs}
            for f in as_completed(futs):
                recs.append(f.result())
        recs.sort(key=lambda r: r["cid"])
        n = len(recs)
        allpass = sum(1 for r in recs if r["all_pass"])
        turnacc = round(sum(r["turn_acc"] for r in recs) / n, 4) if n else 0
        errs = sum(1 for r in recs for t in r["turns"] if t.get("error"))
        s = {"n": n, "all_pass": allpass, "case_acc": round(allpass / n, 4) if n else 0,
             "mean_turn_acc": turnacc, "errors": errs}
        all_res[model] = {"summary": s, "records": recs}
        print(f"  {model:42s} case_acc={s['case_acc']:.3f} turn_acc={turnacc:.3f} ({allpass}/{n}) errs={errs}")
    tag = args.tag or f"v3_{time.strftime('%Y%m%d_%H%M%S')}"
    of = os.path.join(OUT, f"results_{tag}.json")
    json.dump({"stage": "v3", "category": args.category, "elapsed": round(time.time() - t0, 1),
               "n_cases": len(qs), "models": models, "results": all_res},
              open(of, "w", encoding="utf-8"), ensure_ascii=False, indent=1)
    print(f"saved -> {of} ({round(time.time()-t0,1)}s)")
    print("\n== RANKING (case_acc) ==")
    for m, v in sorted(all_res.items(), key=lambda kv: -kv[1]["summary"]["case_acc"]):
        print(f"  {v['summary']['case_acc']:.3f}  {m}")


if __name__ == "__main__":
    main()

